#[expect(clippy::too_many_lines)]
fn run_network_service<P: Preset>(
    mut service: Service<P>,
    mut network_to_service_rx: UnboundedReceiver<ServiceInboundMessage<P>>,
    service_to_network_tx: UnboundedSender<ServiceOutboundMessage<P>>,
) {
    tokio::spawn(async move {
        let mut network_metrics_update_interval =
            IntervalStream::new(tokio::time::interval(NETWORK_METRICS_UPDATE_INTERVAL)).fuse();

        let metrics_enabled = service.network_globals().network_config.metrics_enabled;

        loop {
            tokio::select! {
                _ = network_metrics_update_interval.select_next_some(), if metrics_enabled => {
                    let debug_info = message_debug_info("network_metrics_update_interval");

                    eth2_libp2p::metrics::update_discovery_metrics();
                    eth2_libp2p::metrics::update_sync_metrics(service.network_globals());
                    eth2_libp2p::metrics::update_gossipsub_extended_metrics(
                        service.gossipsub(),
                        service.network_globals(),
                    );

                    debug_info.handle();
                },

                network_event = service.next_event().fuse() => {
                    ServiceOutboundMessage::NetworkEvent(network_event).send(&service_to_network_tx);
                }

                message = network_to_service_rx.select_next_some() => {
                    let debug_info = message_debug_info(&message);

                    match message {
                        ServiceInboundMessage::DiscoverSubnetPeers(subnet_discoveries) => {
                            service.discover_subnet_peers(subnet_discoveries);
                        }

            (effective_balance * max_random_value
                >= P::MAX_EFFECTIVE_BALANCE_ELECTRA * random_value)
                .then_some(candidate_index)
        })
        .ok_or(Error::FailedToSelectProposer)
        .map_err(Into::into)
}

pub(crate) fn compute_proposer_index<P: Preset>(
    config: &Config,
    state: &impl BeaconState<P>,
    indices: &PackedIndices,
    seed: H256,
    epoch: Epoch,
) -> Result<ValidatorIndex> {
    if state.is_post_electra() || epoch >= config.electra_fork_epoch {
        compute_proposer_index_post_electra(state, indices, seed)
    } else {
        compute_proposer_index_pre_electra(state, indices, seed)
    }
}

/// [`compute_subnet_for_attestation`](https://github.com/ethereum/consensus-specs/blob/v1.3.0/specs/phase0/validator.md#broadcast-attestation)
pub fn compute_subnet_for_attestation<P: Preset>(
    committees_per_slot: u64,
    slot: Slot,
    committee_index: CommitteeIndex,
) -> Result<SubnetId> {
    ensure!(
        committee_index < committees_per_slot,
        Error::CommitteeIndexOutOfBounds,
    );

    let slots_since_epoch_start = slots_since_epoch_start::<P>(slot);
    let committees_since_epoch_start = committees_per_slot * slots_since_epoch_start;

    Ok((committees_since_epoch_start + committee_index).mod_typenum::<AttestationSubnetCount>())
}

/// [`compute_subnet_for_blob_sidecar`](https://github.com/ethereum/consensus-specs/blob/v1.4.0-beta.1/specs/deneb/validator.md#sidecar)
pub fn compute_subnet_for_blob_sidecar<P: Preset>(
    config: &Config,
    blob_sidecar: &BlobSidecar<P>,
) -> SubnetId {
    let phase = config.phase_at_slot::<P>(blob_sidecar.signed_block_header.message.slot);

    blob_sidecar.index % config.blob_sidecar_subnet_count(phase)
}

